import Page7 from './pages/Page7.jsx';
import Page8 from './pages/Page8.jsx';
import Page9 from './pages/Page9.jsx';
import Page10 from './pages/Page10.jsx';
const pages={"demo-medical-clinic-1":Page0,"demo-medical-clinic-1-article":Page1,"demo-medical-clinic-1-blog":Page2,"demo-medical-clinic-1-contact":Page3,"demo-medical-clinic-1-doctor":Page4,"demo-medical-clinic-1-doctors":Page5,"demo-medical-clinic-1-locations":Page6,"demo-medical-clinic-1-patients":Page7,"demo-medical-clinic-1-specialties":Page8,"demo-medical-clinic-1-specialty":Page9,"demo-medical-clinic-1-telehealth":Page10};
export default function App(){
const [page,setPage]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('page')||"demo-medical-clinic-1");
useEffect(()=>{const change=()=>setPage(new URLSearchParams(location.hash.slice(1)).get('page')||"demo-medical-clinic-1");const navigate=e=>{const a=e.target.closest('a[href]');const href=a?.getAttribute('href');if(!href?.startsWith('#page='))return;const next=new URLSearchParams(href.slice(1)).get('page');if(!pages[next])return;e.preventDefault();e.stopPropagation();setPage(next);try{if(location.protocol!=='about:')history.pushState(null,'',href)}catch{}};document.addEventListener('click',navigate,true);window.addEventListener('hashchange',change);window.addEventListener('popstate',change);return()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('hashchange',change);window.removeEventListener('popstate',change)}},[]);
useTemplateRuntime(page);const Page=pages[page]||Page0;return <div id='template-page' key={page}><Page/></div>;
}

